def atomic(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix='.flow-tmp-')
    try:
        with os.fdopen(fd, 'w') as f:
